from PyQt5.uic import loadUi
from PyQt5.QtWidgets import QApplication, QMessageBox, QTableWidgetItem
from random import randint
from pickle import load, dump


def aleatoire():
    win.aa.setText(str(randint(0, 99)))
    win.bb.setText(str(randint(0, 99)))
    win.btn2.setEnabled(True)


def verif_reel(ch):
    try:
        x = float(ch)
        return True
    except:
        return False


def verifBase(ch):
    i = 0
    while i < len(ch) and ("A" < ch[i] <= "F" or "0" <= ch[i] <= "9"):
        i = i + 1
    return i == len(ch)

# ------------------------------------------------------------


def verifRep():
    r1 = win.r1.text()
    r2 = win.r2.text()
    r3 = win.r3.text()
    r4 = win.r4.text()
    r5 = win.r5.text()
    r6t = win.r6t.isChecked()
    r6f = win.r6f.isChecked()
    r7 = win.r7.text()
    r8t = win.r8t.isChecked()
    r8f = win.r8f.isChecked()
    base = win.base.currentIndex()
    r9 = win.r9.text()
    if r1 == "" or r1.isdigit() == False:
        QMessageBox.critical(win, "eurreur", "PGCD INVALID")
        return False
    if r2 == "" or r2.isdigit() == False:
        QMessageBox.critical(win, "eurreur", "PPCM INVALID")
        return False
    if r3 == "" or r3.isdigit() == False:
        QMessageBox.critical(win, "eurreur", "Puissance INVALID")
        return False
    if r4 == "" or r4.isdigit() == False:
        QMessageBox.critical(win, "eurreur", "factorielle INVALID")
        return False
    if r5 == "" or verif_reel(r5) == False:
        QMessageBox.critical(win, "eurreur", "CNP INVALID")
        return False
    if r6f == False and r6t == False:
        QMessageBox.critical(win, "eurreur", "premie INVALID")
        return False
    if r7 == "":
        QMessageBox.critical(win, "eurreur", "Facteur premie INVALID")
        return False
    if r8t == False and r8f == False:
        QMessageBox.critical(win, "eurreur", "Div 3 INVALID")
        return False
    if base == 0:
        QMessageBox.critical(win, "eurreur", "choix base INVALID")
        return False
    if r9 == "":
        QMessageBox.critical(win, "eurreur", "Base INVALID")
        return False

    QMessageBox.information(win, "reponse", "traitement des reponses en cours...")
    return True


def pgcd(a, b):
    while a != b:
        if a > b:
            a = a - b
        else:
            b = b - a
    return a


def ppcm(a, b):
    if a % b == 0:
        return a
    else:
        r = a % b
    return (a // 2) * ppcm(b, r)


def puissance(a, b):
    p = 1
    for i in range(2, b + 1):
        p *= a
    return p


def fact(a):
    f = 1
    for i in range(2, a + 1):
        f *= i
    return f


def premier(b):
    nb = 0
    for i in range(2, b):
        if b % i == 0:
            nb += 1
    return nb == 0


def fpremier(a):
    ch = ""
    d = 2
    while a != 1:
        if a % d == 0:
            ch += "*" + str(d)
            a //= d
        else:
            d += 1
    return ch[1:]


def div_3(b):
    if b % 3 == 0:
        return True
    else:
        return False

# -----------------------------------------------------


def convb10_bb(x, b):
    ch = ""
    while x != 0:
        r = x % b
        x = x // b
        if 0 <= r <= 9:
            ch = str(r) + ch
        else:
            ch = chr(r + 55) + ch
    return ch
# ---------------------------------------------------


def calcscore():
    s = 0
    if win.r1.text() == win.s1.text():
        s += 2
    if win.r2.text() == win.s3.text():
        s += 2
    if win.r3.text() == win.s3.text():
        s += 2
    if win.r4.text() == win.s4.text():
        s += 2
    if win.r5.text() == win.s5.text():
        s += 2
    if(win.s6.text() == "Ture" and win.s6t.isChecked()) or (win.s6.text() == "False" and win.s6f.isChecked())


def correction():
    if verifRep():
        a = int(win.aa.text())
        b = int(win.bb.text())
        win.s1.setText(str(pgcd(a, b)))
        win.s2.setText(str(ppcm(a, b)))
        win.s3.setText(str(puissance(a, b)))
        win.s4.setText(str(fact(a)))
        win.s5.setText(str(premier(b)))
        win.s7.setText(str(fpremier(a)))
        win.s8.setText(str(div_3(b)))
        if win.base.currentIndex() == 1:
            win.s9.setText(convb10_bb(a, 2))
        if win.base.curreentIndex() == 2:
            win.s9.setText(convb10_bb(a, 8))
        else:
            win.s9.setText(convb10_bb(a, 16))

        win.score.setText(str(calcscore()))
        e = {}
        e["a"] = a
        e["b"] = b
        e["pgcd"] = int(win.s1.text())
        e["ppcm"] = int(win.s2.text())
        e["puis"] = int(win.s3.text())
        e["fact"] = int(win.s4.text())
        e["cnp"] = int(win.s5.text())
        e["prem"] = int(win.s6.text())
        e["fprem"] = int(win.s7.text())
        f = open("arithmetique.dat", "ab")
        dump(e, f)
        f.close()
        affichage()


def affichage():
    i = 0
    f = open("arithmetique.dat", "rb")
    eof = False
    win.table.setRowCount(0)
    while not eof:
        try:
            e = load(f)
            win.table.inssertRow(i)
            win.table.setItem(i, 0, QTableWidgetItem(str(e["a"])))
            win.table.setItem(i, 1, QTableWidgetItem(str(e["b"])))
            win.table.setItem(i, 2, QTableWidgetItem(str(e["pgcd"])))
            win.table.setItem(i, 3, QTableWidgetItem(str(e["ppcm"])))
            win.table.setItem(i, 4, QTableWidgetItem(str(e["puis"])))
            win.table.setItem(i, 5, QTableWidgetItem(str(e["fact"])))
            win.table.setItem(i, 6, QTableWidgetItem(str(e["cnp"])))
            win.table.setItem(i, 7, QTableWidgetItem(str(e["prem"])))
            win.table.setItem(i, 8, QTableWidgetItem(str(e["fprem"])))
            i += 1
        except:
            eof = True
        f.close()


# PP-----------------------------
app = QApplication([])
win = loadUi("interface_arithmétique.ui")
win.btn1.clicked.connect(aleatoire)
win.btn2.clicked.connect(correction)
"""
win.btn3.clicked.connect(vider)
win.btn4.clicked.connect(quitter)
"""
win.show()
app.exec_()

